import{_ as a,o as s,c as n,ag as e}from"./chunks/framework.CmaAMB6e.js";const g=JSON.parse('{"title":"04 · 存储选型","description":"","frontmatter":{"概念":"存储选型","技能":"system-design","阶段":"1-方法论","状态":"⬜未开始","更新日期":"2026-08-01T00:00:00.000Z","前置":"03 API 与数据流设计","耗时":"1.5~2 小时"},"headers":[],"relativePath":"system-design/concepts/04-storage-selection.md","filePath":"system-design/concepts/04-storage-selection.md","lastUpdated":null}'),d={name:"system-design/concepts/04-storage-selection.md"};function l(r,t,p,i,o,c){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="_04-·-存储选型" tabindex="-1">04 · 存储选型 <a class="header-anchor" href="#_04-·-存储选型" aria-label="Permalink to &quot;04 · 存储选型&quot;">​</a></h1><blockquote><p><strong>前置</strong>：03 API 与数据流设计 · <strong>预计</strong>：1.5~2 小时</p></blockquote><h2 id="概念简介" tabindex="-1">概念简介 <a class="header-anchor" href="#概念简介" aria-label="Permalink to &quot;概念简介&quot;">​</a></h2><p>存储选型回答一个问题：<strong>这批数据用什么数据库存</strong>。没有万能存储——关系型擅长事务与关系查询、文档型擅长可变 schema、键值型擅长高吞吐读、搜索引擎擅长模糊匹配、时序库擅长时间范围聚合。选错的代价极高：数据迁移比代码重构痛苦一个量级，所以选型必须发生在系统设计阶段，而不是上线半年后。</p><p>选型的依据不是「哪个库最流行」，而是三个问题的答案：<strong>数据的模型是什么</strong>（关系/文档/键值/时序）、<strong>数据的访问模式是什么</strong>（点查/范围查/模糊搜/聚合统计）、<strong>一致性与成本要求是什么</strong>。这三者匹配上，选型就完成了大半。</p><p>真实系统几乎不会只用一种存储。成熟的架构往往是「多存储组合」：MySQL 存订单、Redis 扛热点读、ES 做搜索、ClickHouse 做分析——每个组件服务自己的数据子集，这叫 <strong>polyglot persistence（多语言持久化）</strong>。本章最后的组合架构图就是这个思路的落地示范。</p><h2 id="核心内容" tabindex="-1">核心内容 <a class="header-anchor" href="#核心内容" aria-label="Permalink to &quot;核心内容&quot;">​</a></h2><h4 id="_1-存储类型谱系" tabindex="-1">1. 存储类型谱系 <a class="header-anchor" href="#_1-存储类型谱系" aria-label="Permalink to &quot;1. 存储类型谱系&quot;">​</a></h4><table tabindex="0"><thead><tr><th>类型</th><th>代表</th><th>数据模型</th><th>强项</th><th>短板</th></tr></thead><tbody><tr><td>关系型</td><td>MySQL / PostgreSQL</td><td>表 + 外键 + 事务</td><td>一致性、关联查询、成熟</td><td>水平扩展难、模糊搜索弱</td></tr><tr><td>文档型</td><td>MongoDB</td><td>JSON 文档</td><td>灵活 schema、水平扩展</td><td>事务弱（分布式）、关联弱</td></tr><tr><td>键值型</td><td>Redis / Memcached</td><td>key-value</td><td>极高吞吐、毫秒延迟</td><td>只能按 key 查，无复杂查询</td></tr><tr><td>搜索型</td><td>Elasticsearch</td><td>倒排索引</td><td>全文/模糊搜索、聚合</td><td>一致性弱、更新成本高</td></tr><tr><td>时序型</td><td>InfluxDB / Prometheus</td><td>时间序列</td><td>时间范围聚合、压缩比高</td><td>只擅长时序场景</td></tr><tr><td>宽表/列式</td><td>ClickHouse</td><td>列存</td><td>海量数据聚合分析极快</td><td>单行点查/更新弱</td></tr></tbody></table><p>选型判断的捷径：<strong>你被问到最多的那个问题是什么？</strong> 按用户查订单 → 关系型；按标题模糊搜商品 → ES；查股票某天每分钟曲线 → 时序；秒杀扣库存计数 → Redis。</p><h4 id="_2-选型决策树" tabindex="-1">2. 选型决策树 <a class="header-anchor" href="#_2-选型决策树" aria-label="Permalink to &quot;2. 选型决策树&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这批数据要服务什么场景？</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 事务性业务（订单/账务/用户）？ ──是──► 关系型（MySQL/PostgreSQL）</span></span>
<span class="line"><span>│                                        └ 可加 Redis 缓存热点读</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 高频点查 + 极低延迟（会话/计数/热点）？ ──是──► 键值型（Redis）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 全文/模糊搜索（商品/文档/日志关键词）？ ──是──► 搜索型（ES）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ 时间范围聚合（监控指标/埋点/股价）？ ──是──► 时序型</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>├─ schema 频繁变化、团队小、要快速迭代？ ──是──► 文档型（MongoDB）</span></span>
<span class="line"><span>│</span></span>
<span class="line"><span>└─ 都不是但数据量巨大做分析？ ─────────► 列式仓库（ClickHouse）</span></span></code></pre></div><p>注意决策树的顺序即优先级：<strong>先满足事务与一致性，再谈性能</strong>。反例：把订单放进 MongoDB 图快，遇到对账、事务、跨文档一致性时后悔莫及。</p><h4 id="_3-数据访问模式分析-选型的核心动作" tabindex="-1">3. 数据访问模式分析（选型的核心动作） <a class="header-anchor" href="#_3-数据访问模式分析-选型的核心动作" aria-label="Permalink to &quot;3. 数据访问模式分析（选型的核心动作）&quot;">​</a></h4><p>把「业务要查什么」翻译成「存储要支持什么操作」：</p><table tabindex="0"><thead><tr><th>访问模式</th><th>例子</th><th>推荐</th><th>原因</th></tr></thead><tbody><tr><td>点查（按主键取一条）</td><td>按 id 查用户</td><td>任意 + 主键索引</td><td>所有存储都擅长</td></tr><tr><td>范围查（时间/区间）</td><td>查 7 天内的订单</td><td>MySQL 二级索引 / 时序库</td><td>B+ 树与 LSM 天然支持</td></tr><tr><td>关联查询（多表 join）</td><td>订单带商品名</td><td>MySQL（或干脆冗余字段）</td><td>文档型 join 是痛点</td></tr><tr><td>模糊/全文搜索</td><td>搜「红色连衣裙」</td><td>ES</td><td>MySQL LIKE 全表扫描</td></tr><tr><td>聚合分析</td><td>按城市统计 GMV</td><td>列式仓库 / 物化视图</td><td>行存聚合慢一个量级</td></tr><tr><td>高并发计数器</td><td>秒杀库存、点赞数</td><td>Redis（INCR 原子）</td><td>数据库行锁扛不住</td></tr></tbody></table><p>一个判断技巧：<strong>把最重的三个查询写下来，看它们的类型</strong>。如果三个全是「按 id 取详情」，直接单存储 + 缓存；如果混进「模糊搜 + 时间聚合 + 事务」，那就是多存储组合的信号。</p><h4 id="_4-一致性需求" tabindex="-1">4. 一致性需求 <a class="header-anchor" href="#_4-一致性需求" aria-label="Permalink to &quot;4. 一致性需求&quot;">​</a></h4><p>一致性决定你能不能用「性能更好但弱一致」的存储：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>强一致：读到的必须是最新写入（订单状态、余额、库存）</span></span>
<span class="line"><span>  → 关系型 + 事务；读路径也别绕过主库（读写分离有延迟窗口）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>最终一致：允许短暂读到旧值（点赞数、阅读量、feed 时间线）</span></span>
<span class="line"><span>  → Redis / ES / 异步同步；接受「几分钟内看到即可」</span></span>
<span class="line"><span></span></span>
<span class="line"><span>线性一致 vs 因果一致：绝大多数业务到「因果一致」就够</span></span>
<span class="line"><span>  → 别为了「绝对最新」牺牲可用性（CAP：可用性往往更值钱）</span></span></code></pre></div><p>权衡原则：<strong>能用最终一致就别硬上强一致</strong>。强一致的成本是「所有读都打主库 + 分布式事务」，为了一个「点赞数旧了 5 秒」的感知差异付出巨大复杂度，不值。</p><h4 id="_5-成本考量" tabindex="-1">5. 成本考量 <a class="header-anchor" href="#_5-成本考量" aria-label="Permalink to &quot;5. 成本考量&quot;">​</a></h4><ul><li><strong>硬件成本</strong>：行存 vs 列存、冷数据归档（对象存储）、副本数 ×3 的隐性成本。</li><li><strong>运维成本</strong>：一个自建 ES 集群需要专职运维；云托管版省人力但单价高——<strong>人力成本往往大于机器成本</strong>。</li><li><strong>迁移成本</strong>：选错存储的代价 = 双写 + 数据校验 + 切流，按人月计。</li><li>参考做法：<strong>优先选择团队已经熟悉的存储</strong>，除非新存储能带来量级级收益（如 QPS 从万到十万）。</li></ul><h4 id="_6-多存储组合架构" tabindex="-1">6. 多存储组合架构 <a class="header-anchor" href="#_6-多存储组合架构" aria-label="Permalink to &quot;6. 多存储组合架构&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户请求 ──► 应用服务</span></span>
<span class="line"><span>               │</span></span>
<span class="line"><span>      ┌────────┼──────────┬──────────┬────────────┐</span></span>
<span class="line"><span>      ▼        ▼          ▼          ▼            ▼</span></span>
<span class="line"><span>   MySQL    Redis      Elasticsearch  ClickHouse   对象存储</span></span>
<span class="line"><span> 订单/用户  热点读/会话   商品搜索/日志   统计分析/BI   图片/文件</span></span>
<span class="line"><span> 强一致主数据  低延迟缓存    模糊查询        聚合报表      冷数据</span></span></code></pre></div><p>设计原则：<strong>一份数据只有一个「真相源」（Source of Truth）</strong>——比如订单真相在 MySQL，ES 里的订单只是搜索副本，由变更事件（MQ）同步。副本可以丢，可以重建，但真相源不能乱写。这个「主 + 副本」心智模型是整个组合架构的基石。</p><h4 id="_7-数据生命周期-冷热分层与迁移" tabindex="-1">7. 数据生命周期：冷热分层与迁移 <a class="header-anchor" href="#_7-数据生命周期-冷热分层与迁移" aria-label="Permalink to &quot;7. 数据生命周期：冷热分层与迁移&quot;">​</a></h4><p>存储选型不是一次性决策，数据会「变老」——<strong>选型时要问：数据老了以后放哪</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>热数据（最近 30 天订单）：MySQL 主库 → 高频访问，保持高性能</span></span>
<span class="line"><span>温数据（30 天 ~ 1 年）：归档表/独立库 → 低频访问，压缩</span></span>
<span class="line"><span>冷数据（1 年以上）：对象存储（文件/列式压缩包）→ 几乎不访问，成本最低</span></span>
<span class="line"><span></span></span>
<span class="line"><span>迁移手段（别手动搬数据）：</span></span>
<span class="line"><span>  ① TTL/过期策略：Redis/时序库自带自动淘汰（写业务时顺手配置）</span></span>
<span class="line"><span>  ② 定时归档任务：每天把「昨日数据」从热库搬到温库（batch 幂等）</span></span>
<span class="line"><span>  ③ 冷数据只做「按单查询」：设计一个「查历史」入口走冷存储，主查询不进冷库</span></span></code></pre></div><p><strong>成本和性能的权衡在数据层级上同样存在</strong>：热库越「瘦」，查询越快、索引越小；冷库越「胖」，单 GB 成本越低。选型时把「数据会老化」写进设计假设，比事后补迁移方案便宜一个量级。</p><h2 id="常见陷阱" tabindex="-1">常见陷阱 <a class="header-anchor" href="#常见陷阱" aria-label="Permalink to &quot;常见陷阱&quot;">​</a></h2><ul><li><strong>跟风选型</strong>：因为「大家都在用 MongoDB」就换掉 MySQL，没有先问数据模型与访问模式。</li><li><strong>一个存储想装下所有</strong>：订单也想塞进 Redis、搜索也放 MySQL，最后两头都不讨好；组合存储 + 真相源划分才是正道。</li><li><strong>忽略一致性需求就上副本</strong>：读写分离 + 主从延迟，强一致场景读到旧余额导致资损。</li><li><strong>行存跑聚合</strong>：用 MySQL 跑千万级 GROUP BY，慢查询把业务库拖垮；分析场景应该隔离到列式库。</li><li><strong>只算机器成本不算运维成本</strong>：自建 ES 三副本的费用低于云托管，但专职运维的月薪远超差价。</li><li><strong>副本数据直接写</strong>：绕过事件同步直接改 ES/Redis 副本，副本与真相源漂移，恢复时发现「ES 里的才是真的」。</li></ul><h2 id="练习建议" tabindex="-1">练习建议 <a class="header-anchor" href="#练习建议" aria-label="Permalink to &quot;练习建议&quot;">​</a></h2><ol><li><strong>基础</strong>：用决策树为你熟悉的系统（如一个带搜索的电商后台）走一遍选型，输出每个数据表的「存储 + 理由」清单。</li><li><strong>进阶</strong>：设计「订单系统」的多存储组合：MySQL（订单真相源）+ Redis（热点订单缓存）+ ES（订单搜索），画出数据同步链路（真相源 → 副本）并说明同步延迟可接受的原因。</li><li><strong>综合</strong>：分析一个真实场景（短视频 App：视频元数据 + 评论 + 搜索 + 播放统计 + 推荐），为每一类数据做完整选型分析，最后画出组合架构图并标注每个组件的真相源。</li></ol><blockquote><p>用 <code>/practice system-design 存储选型</code> 生成更多针对性练习。</p></blockquote><h2 id="前端对照" tabindex="-1">前端对照 <a class="header-anchor" href="#前端对照" aria-label="Permalink to &quot;前端对照&quot;">​</a></h2><table tabindex="0"><thead><tr><th>前端架构概念</th><th>系统设计对应</th></tr></thead><tbody><tr><td>状态管理选型（Redux vs Zustand vs Context）</td><td>存储选型：按数据特点匹配（全局态=Redis）</td></tr><tr><td>组件状态就近原则（不该提升的不提升）</td><td>数据就近存储（不该进 ES 的不进）</td></tr><tr><td>服务端状态缓存（React Query）</td><td>真相源（数据库）与副本（缓存）分离</td></tr><tr><td>Redux DevTools 时间旅行</td><td>主从复制/备份（可回滚到任意状态）</td></tr><tr><td>组件库选型（AntD vs 自研）</td><td>存储选型：成熟度与人力成本权衡</td></tr><tr><td>全局单例 store vs 页面局部 state</td><td>主数据（MySQL）vs 临时数据（Redis）</td></tr></tbody></table><h2 id="参考链接" tabindex="-1">参考链接 <a class="header-anchor" href="#参考链接" aria-label="Permalink to &quot;参考链接&quot;">​</a></h2><ul><li><a href="https://docs.aws.amazon.com/whitepapers/latest/database-considerations/selecting-database.html" target="_blank" rel="noreferrer">数据库选型官方指南（AWS Architecture）</a></li><li><a href="https://dataintensive.net/" target="_blank" rel="noreferrer">设计数据密集型应用（DDIA）第 3 章：存储引擎</a></li><li><a href="https://martinfowler.com/bliki/PolyglotPersistence.html" target="_blank" rel="noreferrer">Polyglot Persistence 概念（Martin Fowler）</a></li></ul>`,39)])])}const u=a(d,[["render",l]]);export{g as __pageData,u as default};
